import React from 'react';
import {Composition} from 'remotion';
import {FPS, H, W} from './kit';
import {videos} from './videos';

// One composition per folder in src/videos/ (registry is generated by scripts/new_video.sh).
export const RemotionRoot: React.FC = () => (
  <>
    {videos.map((v) => (
      <Composition key={v.id} id={v.id} component={v.component} durationInFrames={v.total} fps={FPS} width={W} height={H} />
    ))}
  </>
);
